B.bmx=s(["Konekte","Se connecter","Sign in"],t.s)
B.brE=s(["Dekonekte","Se d\xe9connecter","Sign out"],t.s)
B.boM=s(["Im\xe8l","Email","Email"],t.s)
B.bNB=s(["Pri renouv\xe8lman","Tarif de renouvellement","Renewal price"],t.s)
B.bMf=s(["Pri enskripsyon, premye pery\xf2d ladan l","Inscription, premi\xe8re p\xe9riode incluse","Registration, first period included"],t.s)
B.bvK=s(["Pri total premye enskripsyon an. Kite vid pou itilize pri renouv\xe8lman an.","Prix total de la premi\xe8re inscription. Vide : m\xeame prix que le renouvellement.","Total first registration price. Leave blank to use the renewal price."],t.s)
B.bKl=s(["Im\xe8l obligatwa pou resevwa konfimasyon enskripsyon ak renouv\xe8lman yo.","Email requis pour recevoir les confirmations d\u2019inscription et de renouvellement.","Email required for registration and renewal confirmations."],t.s)
B.bJ_=s(["Manm ki te deja la","Membre d\xe9j\xe0 inscrit \xe0 la salle","Existing gym member"],t.s)
B.bnV=s(["Reprann yon manm nan ansyen kaye a, san fr\xe8 enskripsyon.","Reprise du registre existant, sans frais d\u2019inscription.","Import from the existing register, without registration fees."],t.s)
B.b4w=s(["Chwazi pery\xf2d li te deja peye a","Choisir la p\xe9riode d\xe9j\xe0 r\xe9gl\xe9e","Choose the previously paid period"],t.s)
B.bit=s(["Pery\xf2d sa a deja peye. Pa gen nouvo lajan k ap antre nan k\xe8s la.","P\xe9riode d\xe9j\xe0 r\xe9gl\xe9e : aucun nouvel encaissement dans la caisse.","Already paid: no new cash receipt will be recorded."],t.s)
B.bb0=s(["Pery\xf2d reprann nan kaye a","P\xe9riode reprise du registre","Period imported from register"],t.s)
B.bmn=s(["Swivi im\xe8l yo","Suivi des emails","Email status"],t.s)
B.bKK=s(["Limit pataje / 24 \xe8dtan","Limite partag\xe9e / 24 heures","Shared limit / 24 hours"],t.s)
B.bp7=s(["An atant","En attente","Queued"],t.s)
B.bn7=s(["Ap voye","En cours","Sending"],t.s)
B.bIp=s(["Voye","Envoy\xe9s","Sent"],t.s)
B.bEU=s(["Pou korije","\xc0 corriger","Needs correction"],t.s)
B.bwb=s(["Pou verifye","\xc0 v\xe9rifier","Needs review"],t.s)
B.aWz=s(["Poz jiska","Pause jusqu\u2019au","Paused until"],t.s)
B.bGS=s(["L\xe8 limit jounen an rive, im\xe8l yo rete an atant epi yo pati otomatikman apre. Kontakte sip\xf2 SecurGYM si gen im\xe8l pou korije oswa verifye.","Limite du jour atteinte : les emails restent en attente et partent automatiquement ensuite. Contactez le support SecurGYM pour les emails \xe0 corriger ou v\xe9rifier.","When the daily limit is reached, emails stay queued and go out automatically later. Contact SecurGYM support about emails needing correction or review."],t.s)
B.aTh=s(["Swivi im\xe8l pa disponib. Verifye ent\xe8n\xe8t ak konfigirasyon s\xe8v\xe8 a.","Suivi indisponible. V\xe9rifiez le r\xe9seau et la configuration serveur.","Email status unavailable. Check the network and server configuration."],t.s)
B.bm0=s(["Im\xe8l konfimasyon an ap voye otomatikman apre senkronizasyon.","L\u2019email de confirmation partira automatiquement apr\xe8s synchronisation.","The confirmation email will be sent automatically after synchronization."],t.s)
B.bvC=s(["Modpas","Mot de passe","Password"],t.s)
